(function(){
  var S=window.OCTICONS;
  window.icon=function(name,size,cls){
    var d=S[name]; if(!d) return '';
    size=size||16;
    var w=Math.round(size*d.w/d.h), h=size;
    return '<svg viewBox="0 0 '+d.w+' '+d.h+'" width="'+w+'" height="'+h+'"'+(cls?' class="'+cls+'"':'')+' aria-hidden="true" fill="currentColor">'+d.p+'</svg>';
  };
  window.iconFill=function(root){
    (root||document).querySelectorAll('[data-icon]').forEach(function(el){
      var n=el.getAttribute('data-icon'), s=parseInt(el.getAttribute('data-size')||'16',10);
      var html=window.icon(n,s); if(html) el.innerHTML=html;
    });
  };
})();
